package com.fitlife.mfe.treinos.bff.service;
import com.fasterxml.jackson.databind.JsonNode;import com.fitlife.mfe.treinos.bff.client.ApiGatewayClient;import org.springframework.http.HttpMethod;import org.springframework.stereotype.Service;
@Service public class TreinosBffService {private final ApiGatewayClient g;public TreinosBffService(ApiGatewayClient g){this.g=g;}public JsonNode usuario(String id,String t){return g.exchange("/api/usuarios/"+id,HttpMethod.GET,null,t);}public JsonNode listar(String id,String t){return g.exchange("/api/treinos/usuario/"+id,HttpMethod.GET,null,t);}public JsonNode salvar(String id,JsonNode d,String t){return g.exchange("/api/treinos/usuario/"+id,HttpMethod.PUT,d,t);}public JsonNode criar(String id,JsonNode d,String t){return g.exchange("/api/treinos/usuario/"+id,HttpMethod.POST,d,t);}}
